result:
.all_btn{
  font-size: 14px;
  padding: 0px
}
.list_btn{
  padding: 0px !important;
}
.page_body{
  position: relative;
  .quick_enter{
    position: absolute;
    top: 4px;
    right: 10px;
    z-index: 99;
  }
  .quick_btn_box{
    display: flex;
    flex-direction: column;
    align-items: center;
    color: #409EFF;
    cursor: pointer;
    i{
      font-size: 25px
    }
    span{
      font-size: 14px;
    }
  }
  .menu_list{
    display: inline-grid;
    grid-template-columns: repeat(9, 11.11%);
    grid-column-gap: 15px;
    // width: calc(100% - 135px);
    width: calc(100% - 120px);
    .menu_item{
      position: relative;
      height: 60px;
      // line-height: 60px;
      text-align: right;
      border-radius: 5px;
      display: flex;
      justify-content: left;
      align-items: center;
      background-size:100% 60px;
      background-repeat: no-repeat;
      cursor: pointer;
      .item{
        position: absolute;
        top: -5px;
        right: -5px;
      }
      .menu_i{
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        margin-left: 14px;
        margin-right: 20px;
        .bottom_i{
          width: 25px;
          height: 19px;
        }

        .top_i{
          width: 10px;
          height: 10px;
        }
      }
    }
    .activeClass{
      box-shadow: 0 2px 4px rgba(0, 0, 0, .12), 0 0 6px rgba(0, 0, 0, .04);
      border: 1px solid
    }
  }
  .table_box{
    margin-top: 15px
  }
  .work_list{
    display: inline-grid;
    grid-template-columns: repeat(5, 20%);
    grid-column-gap: 15px;
    width: calc(100% - 60px);
    .work_item{
      border: 1px solid #EBEEF5;
      border-radius: 10px;
      display: flex;
      padding: 10px;
      width: 95%;
      .icon_box{
        height: 70px;
        width: 70px;
        border-radius: 50%;
        color: #fff;
        text-align: center;
        line-height: 70px;
        font-size: 40px;
        margin-left: 20px
      }
      .order_info{
        flex: auto;
        text-align: center;
        display: flex;
        flex-direction: column;
        justify-content: center;
        .info_name{
          font-weight: 900;
          color: #46506d;
          font-size: 14px
        }
        .info_num{
          font-size: 25px;
          margin-top: 8px;
        }
      }
    }
  }
}
